    if (!configService.isInitialized()) return

    const desktopConfig = readDesktopConfigFromBridge()
    if (desktopConfig) {
        configService.replaceDesktopConfig(desktopConfig)

        return
    }
    if (configService.hasDesktopConfig()) configService.clearDesktopConfig()
}

