            dialogService.error(error, { fallbackMessage: `Local file link could not be opened: ${href}` })
        })
    }

    return (
        <a
            {...anchorProps}
            href={href}
            onClick={handleClick}
            rel={opensOutsideRenderer ? 'noopener noreferrer' : rel}
            target={opensOutsideRenderer ? '_blank' : target}
